#include "ux_support.h"
#include <QCoreApplication>
int main(int argc,char**argv){QCoreApplication app(argc,argv);if(argc!=2)return 64;try{std::filesystem::path data=argv[1];ux::Shell shell(data/"application",data/"main");Canvas canvas(shell);CHECK(shell.choose(0));canvas.ready();CHECK(shell.page()==1&&shell.state()==ux::State::Clean);CHECK(inkHash(shell)==underlay::readBounded(data/"expected1",64));CHECK(shell.action(ux::Action::Show));canvas.changes();CHECK(shell.action(ux::Action::Previous));canvas.ready();CHECK(inkHash(shell)==underlay::readBounded(data/"expected0",64));CHECK(shell.finish(2000));std::puts("UX_FRESH_PROCESS_REOPEN_PASS resume=1 pages=2 exact_ink=true clean_default=true");return 0;}catch(const std::exception& e){std::fprintf(stderr,"UX_REOPEN_FAIL %s\n",e.what());return 1;}}
